from pathlib import Path
import hashlib,json,math,os,plistlib,re,statistics,subprocess,tempfile
root=Path('/private/tmp/logex-audit-130-02gwayfm');image=root/'exfat-raw.dmg';mount=root/'exfat'
os.chdir(root/'live-bundle-probe-e8e8e43e');os.environ['PATH']=str(Path.home()/'.cargo/bin')+os.pathsep+os.environ.get('PATH','')
binaries={'original':root/'baseline-v3-09a63f55-publication-tests','current':root/'ordered-c63fb9ed-publication-tests','diagnostic':root/'live-bundle-e8e8e43e-publication-tests'}
result_path=root/'live-bundle-e8e8e43e-performance.jsonl'
def attached():
 records=plistlib.loads(subprocess.check_output(['hdiutil','info','-plist']));matches=[x for x in records.get('images',[])if Path(x['image-path']).resolve()==image.resolve()];assert len(matches)<=1
 return matches[0] if matches else None
assert image.is_file() and not image.is_symlink() and all(p.is_file()for p in binaries.values()) and attached() is None
assert mount.is_dir() and not mount.is_symlink() and os.stat(mount).st_dev==os.stat(image.parent).st_dev
subprocess.check_call(['hdiutil','attach',str(image),'-mountpoint',str(mount),'-nobrowse'])
try:
 selected=attached();assert selected is not None and any(x.get('mount-point')==str(mount)for x in selected['system-entities'])
 volume=plistlib.loads(subprocess.check_output(['diskutil','info','-plist',str(mount)]));assert volume['FilesystemType']=='exfat'
 with tempfile.TemporaryDirectory(prefix='logex-live-bundle-diag-',dir=mount) as temp, result_path.open('w') as output:
  output.write(json.dumps({'kind':'environment','original':'09a63f55','current':'c63fb9ed (before optional benchmark switch)','diagnostic_only':True,'source_diff':(root/'live-bundle-e8e8e43e-source.diff').read_text(),'builder_source':(root/'live-bundle-e8e8e43e-build.py').read_text(),'runner_source':Path(__file__).read_text(),'binary_sha256':{k:hashlib.sha256(p.read_bytes()).hexdigest()for k,p in binaries.items()},'rustc':subprocess.check_output(['rustc','-Vv'],text=True),'os':subprocess.check_output(['sw_vers'],text=True),'hardware':subprocess.check_output(['sysctl','-n','hw.model','hw.memsize','hw.ncpu'],text=True),'filesystem':'disposable ExFAT image on internal APFS','device':os.stat(temp).st_dev,'conditions':'Three rotating process triplets x three samples. 128 live blocks, 128 rows per nonempty block, checkpoint after every block; exact v3 row/progress/reopen oracles. Current and diagnostic share bounded ordered checkpoint contract; explicit strong API not requested. Diagnostic uses existing immutable bundles for fresh live segments, permits hot bundle descriptors in experimental catalog v7 / segment v5, and handles rollback of a wholly uncommitted first hot bundle. Generic new row-only segments remain raw. This is a feasibility probe, not full recovery/query/maintenance validation. The optional durable-checkpoint switch is disabled in the diagnostic; the current and original fixtures predate that switch. This disposable image is not the protected USB volume. All source restored; not deployed or accepted as correctness/performance fix. Fresh directories; cache not evicted; no concurrent local builds/tests.'})+'\n');output.flush()
  labels=list(binaries)
  for pair in range(3):
   for label in labels[pair:]+labels[:pair]:
    env={**os.environ,'TMPDIR':temp,'LOGEX_PUBLICATION_HEADER_FIELDS':'minimal','LOGEX_PUBLICATION_BLOCKS':'128','LOGEX_PUBLICATION_ROWS_PER_BLOCK':'128','LOGEX_PUBLICATION_HISTORY_BLOCKS':'2048','LOGEX_PUBLICATION_SEGMENT_ROWS':'1000000','LOGEX_PUBLICATION_WARM_HEADERS':'8192','LOGEX_PUBLICATION_REPEATS':'3','LOGEX_PUBLICATION_ROUTE':'live','LOGEX_PUBLICATION_CHECKPOINT_EACH_BLOCK':'1','LOGEX_PUBLICATION_DURABLE_CHECKPOINT':'0'}
    logpath=root/f'live-bundle-e8e8e43e-{pair}-{label}.log'
    with logpath.open('w') as log:r=subprocess.run(['/usr/bin/time','-l',str(binaries[label]),'benchmark_sync_storage_publication','--ignored','--nocapture','--test-threads=1'],env=env,stdout=log,stderr=subprocess.STDOUT)
    if r.returncode:raise RuntimeError(str(logpath))
    for line in logpath.read_text().splitlines():
     if '{' in line:
      try:record=json.loads(line[line.index('{'):])
      except json.JSONDecodeError:continue
      output.write(json.dumps({**record,'pair':pair,'revision':label})+'\n')
     elif 'maximum resident set size' in line:output.write(json.dumps({'kind':'rss','pair':pair,'revision':label,'bytes':int(line.split()[0])})+'\n')
    output.flush();print(pair,label,'passed',flush=True)
  records=[json.loads(x)for x in result_path.read_text().splitlines()];vals={k:[r['elapsed_ms']for r in records if r.get('kind')=='sample' and r['revision']==k]for k in labels};med={k:statistics.median(v)for k,v in vals.items()};summary={'kind':'summary','median_ms':med,'p95_ms':{k:sorted(v)[math.ceil(.95*len(v))-1]for k,v in vals.items()},'change_vs_original':{k:100*(v/med['original']-1)for k,v in med.items()},'diagnostic_change_vs_current':100*(med['diagnostic']/med['current']-1),'samples':{k:len(v)for k,v in vals.items()}};output.write(json.dumps(summary)+'\n');print(summary,flush=True)
finally:
 selected=attached()
 if selected is not None:
  assert any(x.get('mount-point')==str(mount)for x in selected['system-entities'])
  devices=[x['dev-entry']for x in selected['system-entities']if re.fullmatch(r'/dev/disk[0-9]+',x.get('dev-entry',''))];assert len(devices)==1
  subprocess.check_call(['hdiutil','detach',devices[0]])
 assert attached() is None
 print('Disposable image detached',flush=True)
